use proc_macro::{TokenStream, TokenTree};
use rustfft::algorithm::Radix4;
use rustfft::num_complex::Complex32;
use rustfft::{Fft, FftDirection};

pub fn pss_freq(item: TokenStream) -> TokenStream {
    let elems = item.into_iter().collect::<Vec<TokenTree>>();
    if elems.len() == 1
        && let TokenTree::Literal(lit) = &elems[0] && let Ok(n) = lit.to_string().parse::<u8>() {
        let x = generate_pss_sequence_freq(n);
        let s = format!("{:?}", x);
        return s
            .replace("Complex", "num_complex::Complex32")
            .parse()
            .unwrap();
    }
    // Fall through rule
    panic!("pss requires a given n_id2");
}

pub fn pss_time(item: TokenStream) -> TokenStream {
    let elems = item.into_iter().collect::<Vec<TokenTree>>();
    if elems.len() == 1
        && let TokenTree::Literal(lit) = &elems[0] && let Ok(n) = lit.to_string().parse::<u8>() {
        let x = generate_pss_sequence_time(n);
        let s = format!("{:?}", x);
        return s
            .replace("Complex", "num_complex::Complex32")
            .parse()
            .unwrap();
    }
    // Fall through rule
    panic!("pss requires a given n_id");
}

pub fn generate_pss_sequence_freq(n_id2: u8) -> [Complex32; 256] {
    // See TS 138.211 7.4.2.2.1

    let mut x = [0; 127];
    x[0] = 0;
    x[1] = 1;
    x[2] = 1;
    x[3] = 0;
    x[4] = 1;
    x[5] = 1;
    x[6] = 1;

    let mut i = 0;
    while i < 127 - 7 {
        x[i + 7] = x[i + 4] ^ x[i];
        i += 1;
    }

    let offset = 43 * n_id2 as usize;
    let mut d_pss = [0f32; 127];

    let mut n = 0;
    while n < 127 {
        let m = (n + offset) % 127;
        d_pss[n] = (1 - 2 * x[m]) as f32;
        n += 1;
    }

    // Pre-transform array for ifft
    // Previously: d_pss(0), ..., d_pss(126), 0, ..., 0
    // Apply centering: 0(0), ..., 0(63), d_pss(0), ..., d_pss(126), 0(64), ..., 0(128)
    // Apply ifft rotation: d_pss(64), ..., d_pss(126), 0(64), ..., 0(128), 0(0), ..., 0(63), d_pss(0), ..., d_pss(126)

    let mut ret = [Complex32::new(0f32, 0f32); 256];

    let mut i = 0;
    while i < 63 {
        // ret[0..63].copy_from_slice(&d_pss[64..126]);
        ret[i] = Complex32::new(d_pss[i + 64], 0f32);
        i += 1;
    }

    let mut i = 0;
    while i < 64 {
        // ret[63+128..256].copy_from_slice(&d_pss[0..64]);
        ret[64 + 128 + i] = Complex32::new(d_pss[i], 0f32);
        i += 1;
    }

    ret
}

pub fn convert_to_time_domain(pss: &mut [Complex32]) {
    // Perform IFFT
    let fft = Radix4::new(pss.len(), FftDirection::Inverse);
    fft.process(pss);
    let n = pss.len() as f32;

    // Scale result
    for v in &mut *pss {
        *v /= n;
    }
}

pub fn generate_pss_sequence_time(n_id2: u8) -> [Complex32; 256] {
    let mut ret = generate_pss_sequence_freq(n_id2);
    convert_to_time_domain(&mut ret);
    ret
}

